import {computed} from "vue";

const defaultSignColors = {
    water: '#3090FF',
    fire: '#FF332D',
    air: '#27C81F',
    earth: '#676767',
};

const signElements: Record<string, string> = {
    aries: 'fire',
    leo: 'fire',
    sagittarius: 'fire',
    taurus: 'earth',
    virgo: 'earth',
    capricorn: 'earth',
    gemini: 'air',
    libra: 'air',
    aquarius: 'air',
    cancer: 'water',
    scorpio: 'water',
    pisces: 'water',
};

const props = defineProps({
    sign: {
        type: String,
        validator: (value: string) => {
            const validSigns = [
                'aries', 'taurus', 'gemini', 'cancer',
                'leo', 'virgo', 'libra', 'scorpio',
                'sagittarius', 'capricorn', 'aquarius', 'pisces'
            ];
            return validSigns.indexOf(value) !== -1;
        },
        required: true,
    },
    color: {
        type: String,
    },
    width: {
        type: Number,
        default: 64,
    },
    height: {
        type: Number,
        default: 64,
    },
});

const computedColor = computed(() => {
    if (props.color) {
        return props.color;
    }
    const element = signElements[props.sign];
    return defaultSignColors[element as keyof typeof defaultSignColors] || '#ffffff';
});
</script>

